'use client';

import { useMemo, useEffect, useState } from 'react';
import { TokenSource } from 'livekit-client';
import {
  RoomAudioRenderer,
  SessionProvider,
  StartAudio,
  useSession,
  useSessionContext,
} from '@livekit/components-react';
import { useAuth } from '@/contexts/AuthContext';

/**
 * Voice Agent Test Page
 * Multi-tenant LiveKit voice agent for testing
 */

function VoiceAgentUI({ tenantId }: { tenantId: string }) {
  const { isConnected, start, end, agentState, roomName } = useSessionContext();

  return (
    <div className="flex flex-col items-center justify-center min-h-[80vh] p-8">
      {/* Status Header */}
      <div className="mb-8 text-center">
        <h1 className="text-3xl font-bold mb-2">AI Voice Agent Test</h1>
        <p className="text-muted-foreground">
          Tenant: <code className="bg-muted px-2 py-1 rounded">{tenantId}</code>
        </p>
      </div>

      {/* Connection Status */}
      <div className="mb-8">
        {isConnected ? (
          <div className="flex items-center gap-2 text-green-600">
            <div className="h-3 w-3 bg-green-600 rounded-full animate-pulse" />
            Connected - Speak to your AI receptionist
          </div>
        ) : (
          <div className="flex items-center gap-2 text-muted-foreground">
            <div className="h-3 w-3 bg-gray-400 rounded-full" />
            Click Start Call to begin
          </div>
        )}
      </div>

      {/* Control Buttons */}
      <div className="flex gap-4 mb-8">
        {!isConnected ? (
          <button
            onClick={() => start()}
            className="px-8 py-4 bg-primary text-primary-foreground rounded-full text-lg font-semibold hover:bg-primary/90 transition-all shadow-lg"
          >
            🎤 Start Call
          </button>
        ) : (
          <button
            onClick={() => end()}
            className="px-8 py-4 bg-red-600 text-white rounded-full text-lg font-semibold hover:bg-red-700 transition-all shadow-lg"
          >
            📴 End Call
          </button>
        )}
      </div>

      {/* Agent State */}
      {isConnected && (
        <div className="bg-muted/50 rounded-xl p-6 w-full max-w-md">
          <h3 className="font-semibold mb-3">Agent Status</h3>
          <div className="space-y-2 text-sm">
            <div className="flex justify-between">
              <span className="text-muted-foreground">State:</span>
              <span className="font-medium capitalize">{agentState || 'initializing'}</span>
            </div>
            {roomName && (
              <div className="flex justify-between">
                <span className="text-muted-foreground">Room:</span>
                <span className="font-mono text-xs">{roomName}</span>
              </div>
            )}
          </div>
        </div>
      )}

      {/* Instructions */}
      <div className="mt-8 text-center text-sm text-muted-foreground max-w-md">
        <p className="mb-2">💡 Try saying:</p>
        <ul className="space-y-1">
          <li>"I'd like to book an appointment"</li>
          <li>"What services do you offer?"</li>
          <li>"Are you open tomorrow?"</li>
        </ul>
      </div>
    </div>
  );
}

function VoiceAgentSession({ tenantId }: { tenantId: string }) {
  // Use TokenSource.custom() for proper POST body handling
  const tokenSource = useMemo(() => {
    return TokenSource.custom(async () => {
      const res = await fetch('/api/connection-details', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ tenant_id: tenantId }),
      });
      
      if (!res.ok) {
        const errorText = await res.text();
        throw new Error(`Failed to get connection details: ${errorText}`);
      }
      
      return await res.json();
    });
  }, [tenantId]);

  // Create session from tokenSource
  const session = useSession(tokenSource);

  return (
    <SessionProvider session={session}>
      <VoiceAgentUI tenantId={tenantId} />
      <StartAudio label="Enable Audio" />
      <RoomAudioRenderer />
    </SessionProvider>
  );
}

export default function VoiceAgentTestPage() {
  const { user, isLoading } = useAuth();
  const [mounted, setMounted] = useState(false);

  useEffect(() => {
    setMounted(true);
  }, []);

  if (!mounted || isLoading) {
    return (
      <div className="flex items-center justify-center h-screen">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary" />
      </div>
    );
  }

  if (!user?.tenant_id) {
    return (
      <div className="flex flex-col items-center justify-center h-screen">
        <h2 className="text-2xl font-bold mb-4">No Tenant Found</h2>
        <p className="text-muted-foreground">Please log in to test the voice agent.</p>
      </div>
    );
  }

  return <VoiceAgentSession tenantId={user.tenant_id} />;
}
